// Template strings used by sg init / setup. Kept as TS exports for type safety.

export const ENV_SG_EXAMPLE = `# SovGrant backend environment (managed by sg)
# Copy to .env.sg and fill in. SG never configures email providers — you own mail.

NODE_ENV=development
PORT=4000
DATABASE_URL=postgresql://sg:sg@localhost:5432/sg
API_BASE_URL=http://localhost:4000
ALLOWED_ORIGINS=http://localhost:3000

# Secrets (generated by sg init into .env.local — do not commit)
JWT_SECRET=
JWT_ISSUER=sovgrant
JWT_ACCESS_TTL=15m
JWT_REFRESH_TTL=7d
COOKIE_SECRET=
WEBHOOK_SIGNING_SECRET=

# WebAuthn / Passkeys
WEBAUTHN_RP_ID=localhost
WEBAUTHN_RP_NAME=SovGrant
WEBAUTHN_ORIGIN=http://localhost:3000

# Mail — CONSUMER PROVIDED (SG does not configure email)
RESEND_API_KEY=
EMAIL_FROM="SovGrant <noreply@example.com>"

# Optional
UPSTASH_REDIS_REST_URL=
UPSTASH_REDIS_REST_TOKEN=
LOCAL_KMS_KEY=
KMS_PROVIDER=
`;

export const SDK_WIRING_NEXT = `// SovGrant client singleton (managed by sg).
// Mirrors @fusorb/facet-sdk SgClient wiring with 401 auto-refresh.
import { SgClient, AuthSdk } from "@fusorb/facet-sdk";

const BASE_URL = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:4000/api/v1";

let authSdk: AuthSdk;
const client = new SgClient({
  baseUrl: BASE_URL,
  onTokenRefresh: async () => null,
  onAuthCleared: () => {},
});

authSdk = new AuthSdk(client);
export const sgAuth = authSdk;
export const sgClient = client;
`;

export const SG_INTEGRATION_MD = `# SovGrant integration (managed by sg)

## Run the backend
\`\`\`bash
docker compose -f docker-compose.sg.yml up -d
\`\`\`

## Merge the schema
Review \`prisma/schema.sg.prisma\` and merge into \`prisma/schema.prisma\`,
then run \`npx prisma migrate dev --name sg_init\`.

## Seed
\`\`\`bash
pnpm tsx prisma/seed.sg.ts
\`\`\`

## Wire the SDK
Import the generated client from \`src/lib/sg-client.ts\` (or your stack's
equivalent) and wrap your app with the provider.

## Remaining env (consumer-owned)
- RESEND_API_KEY (mail — SG does not configure email providers)
- OAuth provider secrets (GOOGLE_*, GITHUB_*, etc.) if using social login
- Billing keys (STRIPE_*, PAYSTACK_*) if using billing
- KMS keys if using cloud KMS

## Revert
\`sg revert\` restores all files sg created. DB rows are not reverted.
`;
